import React from 'react';

export default function Navbar({ onLoginClick, isLoggedIn, studentName, setCurrentPage, currentPage }) {
  return (
    <header style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '15px 40px',
      backgroundColor: '#ffffff',
      boxShadow: '0 2px 10px rgba(0,0,0,0.03)',
      position: 'sticky',
      top: 0,
      zIndex: 100,
      fontFamily: 'sans-serif'
    }}>
      {/* Logo */}
      <div style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }} onClick={() => setCurrentPage('Home')}>
        <span style={{ fontSize: '24px', fontWeight: 'bold', color: '#15803d' }}>AuraPen</span>
        <span style={{ fontSize: '12px', marginLeft: '5px', color: '#64748b', alignSelf: 'flex-end', marginBottom: '4px' }}>EDUCATION</span>
      </div>

      {/* Navigation Links */}
      <nav style={{ display: 'flex', gap: '30px' }}>
        {['Home', 'Classes', 'Teachers', 'About'].map((page) => (
          <span
            key={page}
            onClick={() => setCurrentPage(page)}
            style={{
              cursor: 'pointer',
              fontSize: '15px',
              fontWeight: currentPage === page ? '600' : '500',
              color: currentPage === page ? '#15803d' : '#475569',
              transition: 'color 0.2s'
            }}
          >
            {page}
          </span>
        ))}
      </nav>

      {/* Login Button OR Admin Welcome Section */}
      <div>
        {isLoggedIn ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            {/* Admin ගේ ෆොටෝ එක වගේ Icon එකක් */}
            <div style={{
              width: '35px',
              height: '35px',
              backgroundColor: '#15803d',
              borderRadius: '50%',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              color: '#fff',
              fontWeight: 'bold',
              fontSize: '16px'
            }}>
              👤
            </div>
            <span style={{ fontWeight: '600', color: '#1e293b', fontSize: '14px' }}>
              Welcome, admin 👋
            </span>
          </div>
        ) : (
          <button
            onClick={onLoginClick}
            style={{
              backgroundColor: '#15803d',
              color: '#ffffff',
              border: 'none',
              padding: '10px 22px',
              borderRadius: '8px',
              fontWeight: '600',
              cursor: 'pointer',
              fontSize: '14px'
            }}
          >
            Login
          </button>
        )}
      </div>
    </header>
  );
}
